import React, { useEffect, useMemo, useState } from "react";
import { Link } from "react-router-dom";
import {
  FaSearch,
  FaLaptop,
  FaKey,
  FaWallet,
  FaBook,
  FaShoppingBag,
  FaIdCard,
  FaWineBottle,
  FaBoxOpen,
  FaArrowRight,
  FaMapMarkerAlt,
  FaCalendarAlt,
  FaCompass,
} from "react-icons/fa";
import "../styles/Home.css"; // Make sure this path is correct

function Home() {
  const [user, setUser] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("All");
  const [isLoaded, setIsLoaded] = useState(false);

  const categories = [
    "All",
    "Watch",
    "Laptop",
    "Bag",
    "Books",
    "ID Cards",
    "Keys",
    "Wallet",
    "Electronics",
    "Clothes",
    "Bottle",
    "Others",
  ];

  const categoryIcons = {
    Watch: "⌚",
    Laptop: <FaLaptop />,
    Bag: <FaShoppingBag />,
    Books: <FaBook />,
    "ID Cards": <FaIdCard />,
    Keys: <FaKey />,
    Wallet: <FaWallet />,
    Electronics: "💻",
    Clothes: "👕",
    Bottle: <FaWineBottle />,
    Others: <FaBoxOpen />,
  };

  const [recentItems] = useState([
    {
      id: 1,
      title: "Apple MacBook Pro",
      category: "Laptop",
      location: "Library Floor 2",
      date: "Oct 24, 2026",
      image:
        "https://images.unsplash.com/photo-1517336714731-489689fd1ca8?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 2,
      title: "Casio Analog Watch",
      category: "Watch",
      location: "Cafeteria",
      date: "Oct 23, 2026",
      image:
        "https://images.unsplash.com/photo-1524592094714-0f0654e20314?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 3,
      title: "Black Nike Backpack",
      category: "Bag",
      location: "Computer Lab 4",
      date: "Oct 22, 2026",
      image:
        "https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=800&q=80",
    },
    {
      id: 4,
      title: "Student ID Card",
      category: "ID Cards",
      location: "Main Gate",
      date: "Oct 21, 2026",
      image:
        "https://images.unsplash.com/photo-1593640408182-31c70c8268f5?auto=format&fit=crop&w=800&q=80",
    },
  ]);

  // Trigger load animation on mount
  useEffect(() => {
    setIsLoaded(true);
    const userData = localStorage.getItem("user");
    if (userData) {
      setUser(JSON.parse(userData));
    }
  }, []);

  const greeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 12) return "Good Morning";
    if (hour < 18) return "Good Afternoon";
    return "Good Evening";
  }, []);

  const filteredItems = recentItems.filter((item) => {
    const matchesCategory =
      activeCategory === "All" || item.category === activeCategory;
    const matchesSearch =
      item.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.location.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCategory && matchesSearch;
  });

  const stats = [
    { title: "Found Items", value: filteredItems.length, icon: "📦" },
    { title: "Categories", value: categories.length - 1, icon: "🏷️" },
    { title: "Welcome", value: user ? user.name : "Guest", icon: "👋" },
  ];

  return (
    <div className={`home-page ${isLoaded ? "loaded" : ""}`}>
      {/* --- HERO SECTION --- */}
      <section className="dashboard-hero slide-down">
        <div className="hero-left">
          <span className="welcome-badge">
            <span className="pulsing-dot"></span>
            {greeting}
          </span>
          <h1>
            {user ? user.name : "Guest"} <span className="wave-emoji">👋</span>
          </h1>
          <p>
            Search and recover lost belongings across your campus in seconds.
            Powered by smart tracking.
          </p>

          <div className="search-bar-container">
            <FaSearch className="search-icon" />
            <input
              className="search-input"
              placeholder="Search items or locations..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            {searchQuery && (
              <button 
                className="clear-search" 
                onClick={() => setSearchQuery('')}
              >
                &times;
              </button>
            )}
          </div>
        </div>

        <div className="hero-right">
          {stats.map((stat, index) => (
            <div 
              className="stat-card glass-panel" 
              key={stat.title}
              style={{ "--delay": `${index * 0.15}s` }}
            >
              <div className="stat-icon-wrapper">
                <span className="stat-icon">{stat.icon}</span>
              </div>
              <div>
                <h2>{stat.value}</h2>
                <p>{stat.title}</p>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* --- CATEGORIES SECTION --- */}
      <section className="category-section fade-up">
        <div className="section-header">
          <h2>
            <FaCompass className="header-icon" /> Browse Categories
          </h2>
        </div>

        <div className="category-pills">
          {categories.map((cat, index) => (
            <button
              key={cat}
              style={{ "--delay": `${index * 0.05}s` }}
              className={`category-pill ${
                activeCategory === cat ? "active" : ""
              }`}
              onClick={() => setActiveCategory(cat)}
            >
              <span className="category-icon">
                {cat === "All" ? "✨" : categoryIcons[cat]}
              </span>
              {cat}
            </button>
          ))}
        </div>
      </section>

      {/* --- RECENT ITEMS SECTION --- */}
      <section className="recent-items-section">
        <div className="section-header fade-up">
          <h2>Recently Found</h2>
          <span className="results-count">{filteredItems.length} Results</span>
        </div>

        {filteredItems.length === 0 ? (
          <div className="empty-message fade-up">
            <div className="empty-icon">🔍</div>
            <h3>No items found</h3>
            <p>We couldn't find anything matching your search criteria.</p>
            <button className="reset-btn" onClick={() => {
                setSearchQuery("");
                setActiveCategory("All");
            }}>
                Reset Filters
            </button>
          </div>
        ) : (
          <div className="card-grid">
            {filteredItems.map((item, index) => (
              <div
                className="item-card fade-up-stagger"
                key={item.id}
                style={{ "--delay": `${index * 0.1}s` }}
              >
                <div className="card-image">
                  <img src={item.image} alt={item.title} loading="lazy" />
                  <span className="badge glass-badge">Found</span>
                </div>

                <div className="card-body">
                  <span className="category-label">{item.category}</span>
                  <h3>{item.title}</h3>

                  <div className="card-info">
                    <p>
                      <div className="info-icon-box">
                        <FaMapMarkerAlt />
                      </div>
                      {item.location}
                    </p>
                    <p>
                      <div className="info-icon-box">
                        <FaCalendarAlt />
                      </div>
                      {item.date}
                    </p>
                  </div>

                  <Link to={`/item/${item.id}`} className="details-btn">
                    <span>View Details</span>
                    <FaArrowRight className="btn-arrow" />
                  </Link>
                </div>
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

export default Home;
